module.exports = function ({ log, options }) {
  const value = options.configuration && options.configuration.headerValue;
  return function addVersionHeader(req, res, next) {
    res.setHeader("X-App-Version", value || "unknown");
    log.verbose("Header added for " + req.path);
    next();
  };
};
